#include <stdlib.h>
#include <stdbool.h>

bool init_freelist_state(struct kmem_cache *cachep, union freelist_init_state *state, unsigned int count) {
    static int random_seed;
    bool has_precomputed = false;

    if (!cachep->random_sequence) {
        random_seed = random();
        state->random_seed = random_seed;
        has_precomputed = false;
    } else {
        state->sequence = cachep->random_sequence;
        state->count = count;
        state->current = random() % count;
        has_precomputed = true;
    }

    return has_precomputed;
}
